#!/bin/bash
# Summarise RESULT lines of diag.py logs: summ.sh <log>...
grep -h "^RESULT" "$@" | sed 's/^RESULT //' | jq -c '{part, which, variant, err: (.error // "" | .[0:300]), ls: {f: .levelset.faces, b: .levelset.bodies, cm: .levelset.closed_manifold, t: (.levelset.seconds|floor)}, dmc: {v: .dev_mc.volume_rel, h: .dev_mc.hausdorff, fq999: .dev_mc.from_ref.q999, tq999: .dev_mc.to_ref.q999, fmean: .dev_mc.from_ref.mean}, rem: (.remesh // {} |{faces, thin_faces_in, watertight, self_intersections, repairs, vol_rel, edge_max}), drem: {v: .dev_remesh.volume_rel, h: .dev_remesh.hausdorff, fq999: .dev_remesh.from_ref.q999}, t_rem: (.t_remesh // 0 | floor), t_gmsh: (.t_gmsh // 0 | floor), peel, gate: (.gate // {} |{dihedral_min, frac_dihedral_lt_5, layers_p01, edge_max_over_h, failures}), n_tets}'
